package v1alpha1

import (
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

// Well-known labels applied to every object generated by the platform operators.
const (
	LabelTenant      = "platform.mycompany.io/tenant"
	LabelEnvironment = "platform.mycompany.io/environment"
	LabelManagedBy   = "platform.mycompany.io/managed-by"

	// ManagedByValue is the value of LabelManagedBy for objects owned by this operator.
	ManagedByValue = "tenant-operator"

	// TenantFinalizer guards cleanup of namespaces (which cannot carry an owner
	// reference to a cluster-scoped object in a way that blocks deletion ordering).
	TenantFinalizer = "platform.mycompany.io/tenant-cleanup"
)

// Condition types reported on Tenant.status.conditions.
const (
	ConditionReady           = "Ready"
	ConditionNamespacesReady = "NamespacesReady"
	ConditionQuotaReady      = "QuotaReady"
	ConditionNetworkReady    = "NetworkPolicyReady"
	ConditionRBACReady       = "RBACReady"
)

// Phase values for Tenant.status.phase.
const (
	PhasePending     = "Pending"
	PhaseReady       = "Ready"
	PhaseFailed      = "Failed"
	PhaseTerminating = "Terminating"
)

// TenantQuota is the aggregate per-namespace resource budget of a tenant.
// Quantities are strings so the CRD stays readable (e.g. "4", "500m", "8Gi");
// they are parsed with resource.ParseQuantity by the controller and webhook.
type TenantQuota struct {
	// CPU is the hard limit for requests.cpu/limits.cpu, e.g. "4" or "4000m".
	// +optional
	// +kubebuilder:validation:Pattern=`^([+-]?[0-9.]+)([eEinumkKMGTP]*[-+]?[0-9]*)$`
	CPU string `json:"cpu,omitempty"`

	// Memory is the hard limit for requests.memory/limits.memory, e.g. "8Gi".
	// +optional
	// +kubebuilder:validation:Pattern=`^([+-]?[0-9.]+)([eEinumkKMGTP]*[-+]?[0-9]*)$`
	Memory string `json:"memory,omitempty"`

	// Storage is the hard limit for requests.storage, e.g. "100Gi".
	// +optional
	// +kubebuilder:validation:Pattern=`^([+-]?[0-9.]+)([eEinumkKMGTP]*[-+]?[0-9]*)$`
	Storage string `json:"storage,omitempty"`

	// Pods is the maximum number of pods per namespace.
	// +optional
	// +kubebuilder:validation:Minimum=0
	Pods int `json:"pods,omitempty"`
}

// TenantSpec defines the desired state of Tenant.
// +kubebuilder:validation:XValidation:rule="!has(self.namespaces) || self.namespaces.all(n, !n.startsWith('kube-') && !(n in ['default', 'kube-system', 'kube-public', 'kube-node-lease']))",message="tenant namespaces must not use reserved names (default, kube-*)"
type TenantSpec struct {
	// DisplayName is a human friendly name for the tenant.
	// +kubebuilder:validation:MinLength=1
	// +kubebuilder:validation:MaxLength=128
	DisplayName string `json:"displayName"`

	// Owners are users (or groups prefixed with "group:") granted the admin
	// ClusterRole in every tenant namespace.
	// +optional
	// +listType=set
	Owners []string `json:"owners,omitempty"`

	// Namespaces to create for this tenant. Names must be DNS-1123 labels.
	// +optional
	// +listType=set
	// +kubebuilder:validation:MaxItems=32
	// +kubebuilder:validation:items:Pattern=`^[a-z0-9]([-a-z0-9]*[a-z0-9])?$`
	// +kubebuilder:validation:items:MaxLength=63
	Namespaces []string `json:"namespaces,omitempty"`

	// Quota applied (as a ResourceQuota) to each tenant namespace.
	// +optional
	Quota TenantQuota `json:"quota,omitempty"`

	// NetworkIsolation installs default-deny NetworkPolicies that only allow
	// traffic between namespaces of the same tenant plus DNS egress.
	// +optional
	NetworkIsolation bool `json:"networkIsolation,omitempty"`
}

// TenantStatus defines the observed state of Tenant.
type TenantStatus struct {
	// Phase is a coarse summary: Pending, Ready, Failed or Terminating.
	// +optional
	Phase string `json:"phase,omitempty"`

	// ObservedGeneration is the .metadata.generation last reconciled.
	// +optional
	ObservedGeneration int64 `json:"observedGeneration,omitempty"`

	// Conditions follow the Kubernetes condition conventions.
	// +optional
	// +listType=map
	// +listMapKey=type
	Conditions []metav1.Condition `json:"conditions,omitempty"`

	// Namespaces currently provisioned for the tenant.
	// +optional
	Namespaces []string `json:"namespaces,omitempty"`
}

// +kubebuilder:object:root=true
// +kubebuilder:subresource:status
// +kubebuilder:resource:scope=Cluster,shortName=tn
// +kubebuilder:printcolumn:name="Display Name",type=string,JSONPath=`.spec.displayName`
// +kubebuilder:printcolumn:name="Phase",type=string,JSONPath=`.status.phase`
// +kubebuilder:printcolumn:name="Isolated",type=boolean,JSONPath=`.spec.networkIsolation`
// +kubebuilder:printcolumn:name="Age",type=date,JSONPath=`.metadata.creationTimestamp`

// Tenant is a team or business unit that owns a set of namespaces on the platform.
type Tenant struct {
	metav1.TypeMeta   `json:",inline"`
	metav1.ObjectMeta `json:"metadata,omitempty"`

	Spec   TenantSpec   `json:"spec,omitempty"`
	Status TenantStatus `json:"status,omitempty"`
}

// +kubebuilder:object:root=true

// TenantList contains a list of Tenant.
type TenantList struct {
	metav1.TypeMeta `json:",inline"`
	metav1.ListMeta `json:"metadata,omitempty"`
	Items           []Tenant `json:"items"`
}

func init() {
	SchemeBuilder.Register(&Tenant{}, &TenantList{})
}
